// src/components/AdminLayout.tsx

import React, { useState } from 'react';
import { Outlet, useLocation, useNavigate } from 'react-router-dom';
import {
    MenuFoldOutlined, MenuUnfoldOutlined, DashboardOutlined, ShoppingOutlined, UserOutlined, TableOutlined, PlusOutlined, SettingOutlined,
} from '@ant-design/icons';
import { Button, Layout, Menu, theme } from 'antd';

const { Header, Sider, Content } = Layout;

const AdminLayout: React.FC = () => {
    const [collapsed, setCollapsed] = useState(false);
    const { token: { colorBgContainer, borderRadiusLG } } = theme.useToken();
    const navigate = useNavigate();
    const location = useLocation();

    const menuItems = [
        { key: '/admin', icon: <DashboardOutlined />, label: 'Dashboard' },

        {
            key: 'sub-users',
            icon: <SettingOutlined />,
            label: 'Quản Lý Người Dùng',
            children: [
                { key: '/admin/users', icon: <UserOutlined />, label: 'Danh sách Người dùng' },
                { key: '/admin/users/add', icon: <UserOutlined />, label: 'Thêm Người dùng' },
                { key: '/admin/users/update', icon: <UserOutlined />, label: 'Cập nhật Người dùng' },
            ],
        },

        {
            key: 'sub-nhacungcap',
            icon: <SettingOutlined />,
            label: 'Quản Lý Nhà Cung Cấp',
            children: [
                { key: '/admin/nhacungcap', icon: <UserOutlined />, label: 'Danh sách Nhà cung cấp' },
                { key: '/admin/nhacungcap/add', icon: <UserOutlined />, label: 'Thêm Nhà cung cấp' },
                { key: '/admin/nhacungcap/update', icon: <UserOutlined />, label: 'Cập nhật Nhà cung cấp' },
            ],
        },

        {
            key: 'sub-hanghoa',
            icon: <ShoppingOutlined />,
            label: 'Sản Phẩm & Nguyên Liệu',
            children: [
                // Mục con 1: Quản lý Loại Sản phẩm
                { key: '/admin/loaisanpham', icon: <TableOutlined />, label: 'Danh mục Loại SP' },

                // Mục con 2: Quản lý Sản phẩm
                {
                    key: 'sanpham', 
                    label: 'Quản lý Sản phẩm',
                    children: [ 
                        { key: '/admin/sanpham', icon: <TableOutlined />, label: 'Danh sách SP' },
                        { key: '/admin/sanpham/add', icon: <PlusOutlined />, label: 'Thêm Sản phẩm' },
                    ],
                },

                // Mục con 3: Quản lý Nguyên liệu
                {
                    key: 'nguyenlieu',
                    label: 'Quản lý Nguyên liệu',
                    children: [
                        { key: '/admin/nguyenlieu', icon: <TableOutlined />, label: 'Danh sách NL' },
                        { key: '/admin/nguyenlieu/add', icon: <PlusOutlined />, label: 'Thêm Nguyên liệu' },
                    ],
                },
            ],
        },

        // --- 3. NHÓM HÓA ĐƠN (SubMenu) ---
        {
            key: 'sub-hoadon',
            icon: <SettingOutlined />,
            label: 'Quản Lý Hóa Đơn',
            children: [
                { key: '/admin/hoadonban', icon: <TableOutlined />, label: 'Hóa đơn Bán' },
                { key: '/admin/hoadonnhap', icon: <TableOutlined />, label: 'Hóa đơn Nhập' },
                // { key: '/admin/hoadonban/add', icon: <PlusOutlined />, label: 'Tạo Hóa đơn bán mới' }, // Tùy chọn
            ],
        },
    ];

    return (
        <Layout style={{ minHeight: '100vh' }}>
            <Sider trigger={null} collapsible collapsed={collapsed} width={250} collapsedWidth={80}>
                <div className="demo-logo-vertical" style={{ height: 32, margin: 16, background: 'rgba(255, 255, 255, 0.2)', borderRadius: 6 }} />

                <Menu
                    theme="dark"
                    mode="inline"
                    selectedKeys={[location.pathname]}
                    items={menuItems}
                    onClick={({ key }) => navigate(key)}
                />
            </Sider>
            <Layout>
                <Header style={{ padding: 0, background: colorBgContainer }}>
                    <Button
                        type="text"
                        icon={collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />}
                        onClick={() => setCollapsed(!collapsed)}
                        style={{ fontSize: '16px', width: 64, height: 64 }}
                    />
                </Header>
                <Content
                    style={{ margin: '24px 16px', padding: 24, minHeight: 280, background: colorBgContainer, borderRadius: borderRadiusLG }}
                >
                    {/* THÊM <Outlet /> ĐỂ HIỂN THỊ NỘI DUNG ROUTE CON */}
                    <Outlet />
                </Content>
            </Layout>
        </Layout>
    );
};

export default AdminLayout;
